package com.enerlution.ems.business;

import com.enerlution.ems.common.BusinessException;
import com.enerlution.ems.tenant.TenantGrantService;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Canonical asset writes. Local assets never acquire reference-import provenance. */
@Service
public class ReferenceLifecycleService {
 private final DomainSupport s; private final TenantGrantService grants;
 private static final ObjectMapper JSON=new ObjectMapper();
 public ReferenceLifecycleService(DomainSupport s,TenantGrantService grants){this.s=s;this.grants=grants;}
 private void lock(){s.db.execute("SELECT pg_advisory_xact_lock(78291002)");s.db.execute("SELECT pg_advisory_xact_lock(78291001)");}
 private static BusinessException bad(String message){return new BusinessException(400,message);}
 private static String text(Map<String,Object> b,String key,int max,boolean required){Object value=b.get(key);if(value!=null&&!(value instanceof String))throw bad("字段格式无效："+key);String v=value==null?null:value.toString().strip();if(v!=null&&v.length()>max||required&&(v==null||v.isBlank()))throw bad("请填写有效的"+key);return v==null||v.isBlank()?null:v;}
 private static BigDecimal decimal(Map<String,Object> b,String key,BigDecimal min,BigDecimal max){Object raw=b.get(key);if(raw==null||"".equals(raw))return null;try{BigDecimal v=new BigDecimal(raw.toString());if(v.compareTo(min)<0||v.compareTo(max)>0||v.scale()>7)throw bad("数值超出范围："+key);return v;}catch(NumberFormatException ex){throw bad("数值无效："+key);}}
 private static BigDecimal capacity(Map<String,Object>b,String key){return decimal(b,key,BigDecimal.ZERO,new BigDecimal("99999999999"));}
 private static Long number(Map<String,Object>b,String key,boolean required){Object raw=b.get(key);if(raw==null&&!required)return null;try{String str=Objects.toString(raw,"");if(!str.matches("[0-9]{1,18}"))throw new NumberFormatException();long v=Long.parseLong(str);if(v<1)throw new NumberFormatException();return v;}catch(NumberFormatException ex){throw bad("编号无效："+key);}}
 private static void version(Map<String,Object>b,Map<String,Object>row){Object raw=b.get("expectedVersion");if(raw==null||!raw.toString().matches("[0-9]{1,18}"))throw bad("缺少有效版本");if(Long.parseLong(raw.toString())!=((Number)row.get("lifecycle_version")).longValue())throw new BusinessException(409,"记录已被更新，请刷新后重试");}
 private Map<String,Object> ownStation(long id,String permission,boolean writing){s.access.requireStationPermission(id,permission);var r=s.one("SELECT * FROM station WHERE id=?"+(writing?" FOR UPDATE":""),id);if(s.number(r,"tenant_id")!=s.access.context().tenantId())throw new BusinessException(403,"仅支持当前企业场站");if(r.get("archived_at")!=null)throw new BusinessException(410,"场站已归档");return r;}
 private Map<String,Object> ownDevice(long id,boolean writing){var r=s.one("SELECT * FROM device WHERE id=?"+(writing?" FOR UPDATE":""),id);ownStation(s.number(r,"station_id"),writing?"asset.edit":"asset.read",writing);if(r.get("archived_at")!=null)throw new BusinessException(410,"设备已归档");return r;}
 private boolean canCreate(){var a=s.access.context();return a.administrator()&&"enterprise".equals(a.kind())&&s.access.hasPermission("asset.edit");}
 public Map<String,Object> options(){
  var a=s.access.context();var stations=s.db.queryForList("SELECT st.id::text,st.name FROM station st WHERE st.tenant_id=? AND st.archived_at IS NULL AND (st.replica_visible OR EXISTS(SELECT 1 FROM station_reference_import i WHERE i.station_id=st.id)) AND EXISTS(SELECT 1 FROM saas_effective_station_permission p WHERE p.station_id=st.id AND p.user_id=? AND p.client=? AND p.permission_code='asset.edit') ORDER BY st.name",a.tenantId(),a.actorId(),s.access.client());
  List<Map<String,Object>> members=List.of();Object roles=List.of();if(s.access.hasPermission("company.grant.manage")){members=s.db.queryForList("SELECT id::text,display_name AS name FROM app_user WHERE tenant_id=? AND status='active' AND NOT EXISTS(SELECT 1 FROM tenant_administrator a WHERE a.user_id=app_user.id) ORDER BY display_name",a.tenantId());var rawRoles=(List<?>)grants.options().get("roles");roles=rawRoles.stream().map(raw->{var r=(Map<?,?>)raw;return Map.of("id",r.get("id").toString(),"name",r.get("name"),"source",r.get("source"));}).toList();}
  return Map.of("canCreate",canCreate(),"stations",stations,"members",members,"roles",roles);
 }
 private static String encode(Object v){try{return JSON.writeValueAsString(v);}catch(Exception ex){throw bad("资料格式无效");}}
 private static Map<String,Object> object(Object raw){try{return raw==null?new LinkedHashMap<>():JSON.readValue(raw.toString(),new TypeReference<LinkedHashMap<String,Object>>(){});}catch(Exception ex){throw new IllegalStateException(ex);}}
 private static java.sql.Date date(Map<String,Object>b,String key){String value=text(b,key,10,false);try{return value==null?null:java.sql.Date.valueOf(LocalDate.parse(value));}catch(Exception ex){throw bad("日期无效："+key);}}
 private Map<String,Object> validateStation(Map<String,Object>b){
  for(String k:List.of("name","address","region","timezone","siteType"))text(b,k,k.equals("address")?300:k.equals("name")?160:80,true);
  try{ZoneId.of(b.get("timezone").toString());}catch(Exception ex){throw bad("时区无效");}
  if(!Set.of("residential","commercial","ground").contains(b.get("siteType")))throw bad("场站类型无效");
  if(!(b.get("systems") instanceof List<?> systems)||systems.isEmpty()||systems.size()>3||new HashSet<>(systems).size()!=systems.size()||!Set.of("PV","BESS","EV").containsAll(systems)||!systems.contains("PV")&&!systems.contains("BESS"))throw bad("请选择光伏或储能系统");
  if(decimal(b,"longitude",new BigDecimal("-180"),new BigDecimal("180"))==null||decimal(b,"latitude",new BigDecimal("-90"),new BigDecimal("90"))==null)throw bad("请填写经纬度");
  for(String k:List.of("solarCapacityKw","ratedPowerKw","capacityKwh")){var value=capacity(b,k);if(!k.equals("solarCapacityKw")&&value!=null&&value.signum()==0)throw bad("已知储能容量与功率必须大于零，未知请留空");}
  for(String k:List.of("country","province","city"))text(b,k,100,false);date(b,"commissionedOn");date(b,"gridConnectionDate");
  Object raw=b.getOrDefault("relatedParties",List.of());if(!(raw instanceof List<?> parties)||parties.size()>30)throw bad("关联方数量无效");
  var clean=new ArrayList<Map<String,Object>>();for(Object item:parties){if(!(item instanceof Map<?,?>))throw bad("关联方格式无效");@SuppressWarnings("unchecked") var party=(Map<String,Object>)item;var p=new LinkedHashMap<String,Object>();for(String k:List.of("type","name","phone","email","company"))p.put(k,text(party,k,160,false));if(p.get("email")!=null&&!p.get("email").toString().matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))throw bad("关联方邮箱无效");clean.add(p);}
  var detail=new LinkedHashMap<String,Object>();detail.put("systems",b.get("systems"));detail.put("siteType",b.get("siteType"));detail.put("relatedParties",clean); for(String key:List.of("generationAccount","solarConsumptionMode","solarGridStatus","storageGridStatus"))detail.put(key,text(b,key,160,false)); detail.put("voltageLevelKv",decimal(b,"voltageLevelKv",BigDecimal.ZERO,new BigDecimal("1000")));detail.put("moduleAzimuth",decimal(b,"moduleAzimuth",new BigDecimal("-180"),new BigDecimal("360")));detail.put("moduleTilt",decimal(b,"moduleTilt",BigDecimal.ZERO,new BigDecimal("90")));return detail;
 }
 public Map<String,Object> station(long id){var row=ownStation(id,"asset.read",false);var out=new LinkedHashMap<String,Object>();out.put("id",Long.toString(id));out.put("version",s.number(row,"lifecycle_version"));
  for(var p:List.of(new String[]{"name","name"},new String[]{"address","address"},new String[]{"region","region"},new String[]{"longitude","longitude"},new String[]{"latitude","latitude"},new String[]{"ratedPowerKw","rated_power_kw"},new String[]{"capacityKwh","capacity_kwh"}))out.put(p[0],row.get(p[1]));
  var profiles=s.db.queryForList("SELECT * FROM station_profile WHERE station_id=?",id);if(!profiles.isEmpty()){var p=profiles.getFirst();for(var f:List.of(new String[]{"timezone","timezone"},new String[]{"country","country"},new String[]{"province","province"},new String[]{"city","city"},new String[]{"solarCapacityKw","solar_capacity_kw"},new String[]{"commissionedOn","commissioned_on"},new String[]{"gridConnectionDate","grid_connection_date"}))out.put(f[0],p.get(f[1]) instanceof java.sql.Date d?d.toString():p.get(f[1]));var details=object(p.get("details"));for(String key:List.of("systems","siteType","relatedParties","generationAccount","solarConsumptionMode","solarGridStatus","storageGridStatus","voltageLevelKv","moduleAzimuth","moduleTilt"))if(details.containsKey(key))out.put(key,details.get(key));}
  var normalized=new LinkedHashSet<String>();if(out.get("systems") instanceof List<?> systems)for(Object system:systems){String value=switch(Objects.toString(system,"")){case "PV","Solar System","MPPT PV System"->"PV";case "BESS","Storage System"->"BESS";case "EV","Charging System"->"EV";default->"";};if(!value.isEmpty())normalized.add(value);}out.put("systems",normalized.isEmpty()?(row.get("asset_type").equals("Hybrid")?List.of("PV","BESS"):List.of(row.get("asset_type"))):List.copyOf(normalized));if(!Set.of("residential","commercial","ground").contains(Objects.toString(out.get("siteType"),"")))out.put("siteType",switch(Objects.toString(out.get("siteType"),"")){case "户用","Residential"->"residential";case "地面","Ground"->"ground";default->"commercial";});out.putIfAbsent("relatedParties",List.of());return out;
 }
 @Transactional public Map<String,Object> createStation(Map<String,Object>b){lock();if(!canCreate())throw new BusinessException(403,"仅企业管理员可创建场站");var detail=validateStation(b);String scene=scene(b);long id=s.db.queryForObject("INSERT INTO station(code,name,tenant_id,asset_type,rated_power_kw,capacity_kwh,address,region,longitude,latitude,replica_visible) VALUES(?,?,?,?,?,?,?,?,?,?,true) RETURNING id",Long.class,"LOCAL-"+UUID.randomUUID(),text(b,"name",160,true),s.access.context().tenantId(),scene,capacity(b,"ratedPowerKw"),capacity(b,"capacityKwh"),b.get("address"),b.get("region"),b.get("longitude"),b.get("latitude"));profile(id,b,detail);s.auditStation("station.create",id,Map.of("stationId",id));return station(id);}
 private String scene(Map<String,Object>b){var systems=(List<?>)b.get("systems");return systems.contains("PV")&&systems.contains("BESS")?"Hybrid":systems.contains("PV")?"PV":"BESS";}
 private void profile(long id,Map<String,Object>b,Map<String,Object>detail){s.db.update("INSERT INTO station_profile(station_id,timezone,solar_capacity_kw,commissioned_on,grid_connection_date,country,province,city,details) VALUES(?,?,?,?,?,?,?,?,?::jsonb) ON CONFLICT(station_id) DO UPDATE SET timezone=excluded.timezone,solar_capacity_kw=excluded.solar_capacity_kw,commissioned_on=excluded.commissioned_on,grid_connection_date=excluded.grid_connection_date,country=excluded.country,province=excluded.province,city=excluded.city,details=station_profile.details||excluded.details,updated_at=now()",id,b.get("timezone"),capacity(b,"solarCapacityKw"),date(b,"commissionedOn"),date(b,"gridConnectionDate"),b.get("country"),b.get("province"),b.get("city"),encode(detail));}
 @Transactional public Map<String,Object> updateStation(long id,Map<String,Object>b){lock();var row=ownStation(id,"asset.edit",true);version(b,row);var detail=validateStation(b);var power=capacity(b,"ratedPowerKw");
  if(Boolean.TRUE.equals(s.db.queryForObject("SELECT EXISTS(SELECT 1 FROM plan_period p JOIN operating_plan o ON o.id=p.plan_id WHERE o.station_id=? AND (?::numeric IS NULL OR p.power_kw>?))",Boolean.class,id,power,power)))throw new BusinessException(409,"额定功率低于既有计划功率");
  var commitments=s.db.query("SELECT m.starts_at,m.ends_at,a.capacity_kw FROM market_allocation a JOIN market_service m ON m.id=a.service_id WHERE a.station_id=? AND m.status NOT IN ('cancelled','withdrawn') AND m.ends_at>now()",(rs,n)->new BusinessRules.CapacityWindow(rs.getTimestamp(1).toInstant(),rs.getTimestamp(2).toInstant(),rs.getBigDecimal(3)),id);if(!commitments.isEmpty()&&(power==null||BusinessRules.peakCapacity(commitments).compareTo(power)>0))throw new BusinessException(409,"额定功率低于已有市场承诺");
  s.db.update("UPDATE station SET name=?,asset_type=?,rated_power_kw=?,capacity_kwh=?,address=?,region=?,longitude=?,latitude=? WHERE id=?",text(b,"name",160,true),scene(b),power,capacity(b,"capacityKwh"),b.get("address"),b.get("region"),b.get("longitude"),b.get("latitude"),id);profile(id,b,detail);s.auditStation("station.edit",id,Map.of("stationId",id));return station(id);}
 @Transactional public Map<String,Object> archiveStation(long id,Map<String,Object>b){lock();var r=ownStation(id,"asset.edit",true);version(b,r);if(Boolean.TRUE.equals(s.db.queryForObject("SELECT EXISTS(SELECT 1 FROM ems_binding_period WHERE station_id=? AND valid_to IS NULL)",Boolean.class,id)))throw new BusinessException(409,"请先解除场站采集连接后归档");s.db.update("UPDATE station SET archived_at=now() WHERE id=?",id);s.auditStation("station.archive",id,Map.of("stationId",id));return Map.of("id",Long.toString(id),"archived",true,"version",s.number(r,"lifecycle_version")+1);}
 @Transactional public Map<String,Object> assignStation(long id,Map<String,Object>b){lock();var r=ownStation(id,"asset.edit",true);version(b,r);long user=number(b,"userId",true);long grant=grants.create(new TenantGrantService.Grant(user,number(b,"roleId",false),number(b,"templateId",false),List.of(id),null,null));s.db.update("UPDATE station SET manager_id=? WHERE id=?",user,id);s.auditStation("station.assign",id,Map.of("userId",user,"grantId",grant));return station(id);}
 private static String category(String type){return switch(type){case "inverter"->"PV";case "cabinet"->"BESS";case "pcs"->"PCS";case "battery-cluster","battery-stack"->"BMS";case "air-conditioner"->"HVAC";case "meter"->"MTR";default->"OTHER";};}
 private void validateDevice(Map<String,Object>b){text(b,"name",120,true);text(b,"serial",120,true);String type=text(b,"type",100,true);if(!ReferenceDeviceListService.TYPES.contains(type))throw bad("设备类型无效");text(b,"model",120,false);text(b,"manufacturer",120,false);capacity(b,"ratedPowerKw");capacity(b,"capacityKwh");}
 public Map<String,Object> device(long id){var r=ownDevice(id,false);var out=new LinkedHashMap<String,Object>();out.put("id",Long.toString(id));out.put("stationId",r.get("station_id").toString());out.put("version",s.number(r,"lifecycle_version"));out.put("name",r.get("name"));out.put("serial",r.get("serial_number"));var profiles=s.db.queryForList("SELECT * FROM device_reference_profile WHERE device_id=?",id);if(!profiles.isEmpty()){var p=profiles.getFirst();out.put("type",DeviceDetailRules.type(p.get("source_type").toString(),p.get("category").toString()));for(var f:List.of(new String[]{"model","model"},new String[]{"manufacturer","manufacturer"},new String[]{"ratedPowerKw","rated_power_kw"},new String[]{"capacityKwh","capacity_kwh"}))out.put(f[0],p.get(f[1]));}return out;}
 private void deviceProfile(long id,Map<String,Object>b){s.db.update("INSERT INTO device_reference_profile(device_id,source_type,category,model,manufacturer,rated_power_kw,capacity_kwh) VALUES(?,?,?,?,?,?,?) ON CONFLICT(device_id) DO UPDATE SET source_type=excluded.source_type,category=excluded.category,model=excluded.model,manufacturer=excluded.manufacturer,rated_power_kw=excluded.rated_power_kw,capacity_kwh=excluded.capacity_kwh,updated_at=now()",id,b.get("type"),category(b.get("type").toString()),b.get("model"),b.get("manufacturer"),capacity(b,"ratedPowerKw"),capacity(b,"capacityKwh"));}
 @Transactional public Map<String,Object> createDevice(Map<String,Object>b){lock();long station=number(b,"stationId",true);ownStation(station,"asset.edit",true);validateDevice(b);uniqueSerial(b,0);long id=s.db.queryForObject("INSERT INTO device(station_id,code,name,serial_number) VALUES(?,?,?,?) RETURNING id",Long.class,station,"LOCAL-"+UUID.randomUUID(),text(b,"name",120,true),text(b,"serial",120,true));deviceProfile(id,b);s.auditStation("device.create",station,Map.of("deviceId",id));return device(id);}
 private void uniqueSerial(Map<String,Object>b,long id){if(Boolean.TRUE.equals(s.db.queryForObject("SELECT EXISTS(SELECT 1 FROM device WHERE serial_number=? AND id<>?)",Boolean.class,text(b,"serial",120,true),id)))throw new BusinessException(409,"设备序列号已存在");}
 @Transactional public Map<String,Object> updateDevice(long id,Map<String,Object>b){lock();var r=ownDevice(id,true);version(b,r);validateDevice(b);if(number(b,"stationId",true)!=s.number(r,"station_id"))throw bad("请使用分配功能变更场站");uniqueSerial(b,id);s.db.update("UPDATE device SET name=?,serial_number=? WHERE id=?",text(b,"name",120,true),text(b,"serial",120,true),id);deviceProfile(id,b);s.auditStation("device.edit",s.number(r,"station_id"),Map.of("deviceId",id));return device(id);}
 private void movable(long id){if(Boolean.TRUE.equals(s.db.queryForObject("SELECT EXISTS(SELECT 1 FROM device_binding WHERE device_id=?) OR EXISTS(SELECT 1 FROM ems_gateway WHERE device_id=?) OR EXISTS(SELECT 1 FROM measurement_point WHERE device_id=?) OR EXISTS(SELECT 1 FROM topology_connection WHERE source_device_id=? OR target_device_id=?) OR EXISTS(SELECT 1 FROM station_space_device WHERE device_id=?) OR EXISTS(SELECT 1 FROM substation_device WHERE device_id=?) OR EXISTS(SELECT 1 FROM alarm WHERE device_id=?)",Boolean.class,id,id,id,id,id,id,id,id)))throw new BusinessException(409,"设备已有测点、采集绑定或空间拓扑关系，不能跨场站移动");}
 @Transactional public Map<String,Object> assignDevice(long id,Map<String,Object>b){lock();var r=ownDevice(id,true);version(b,r);long target=number(b,"stationId",true),old=s.number(r,"station_id");ownStation(target,"asset.edit",true);if(target==old)return device(id);movable(id);s.db.update("UPDATE device SET station_id=? WHERE id=?",target,id);s.auditStations("device.assign",List.of(old,target),Map.of("deviceId",id,"fromStationId",old,"toStationId",target));return device(id);}
 @Transactional public Map<String,Object> archiveDevice(long id,Map<String,Object>b){lock();var r=ownDevice(id,true);version(b,r);if(Boolean.TRUE.equals(s.db.queryForObject("SELECT EXISTS(SELECT 1 FROM device_binding WHERE device_id=? AND valid_to IS NULL) OR EXISTS(SELECT 1 FROM ems_gateway g JOIN ems_binding_period p USING(ems_uuid) WHERE g.device_id=? AND p.valid_to IS NULL)",Boolean.class,id,id)))throw new BusinessException(409,"请先解除设备采集连接后归档");s.db.update("UPDATE device SET archived_at=now() WHERE id=?",id);s.auditStation("device.archive",s.number(r,"station_id"),Map.of("deviceId",id));return Map.of("id",Long.toString(id),"archived",true,"version",s.number(r,"lifecycle_version")+1);}
}
